const section=(title,text,extra={})=>({title,text,...extra});
const chapter=(id,title,kicker,summary,structures,sections,extra={})=>({id,title,kicker,summary,structures,sections,...extra});
export const SYNAPSE_COURSE={id:'c4',number:'04',title:'Synapses et intégration neuronale',subtitle:'De la libération des neurotransmetteurs aux réseaux et à l’épilepsie',source:'./assets/cours-4.txt',chapters:[
chapter('c4-synapse','Comment deux neurones communiquent','Pré, fente, post','Relier le potentiel d’action du cours 3 à la transmission synaptique.',['synapse','vesicles','terminals','dendrites','initialSegment'],[
section('Le point de départ : un signal électrique','Dans l’exemple du cours, le neurone est au repos vers −70 mV et son seuil est illustré vers −50 mV. Une dépolarisation suffisante peut déclencher un potentiel d’action, généralement au segment initial. Le PA se propage jusqu’aux terminaisons de l’axone. Mais son arrivée dans un bouton ne signifie pas que le neurone suivant produira automatiquement un PA : la synapse transmet un signal qui devra être intégré.'),
section('Présynaptique et postsynaptique','Le compartiment présynaptique envoie le message ; le compartiment postsynaptique le reçoit. « Pré » et « post » décrivent leur place dans cette communication, pas deux catégories définitives de neurones. Une même cellule peut recevoir des milliers de signaux et en envoyer à de nombreuses cibles. Le cours travaille surtout sur une terminaison axonale faisant face à une membrane dendritique ou somatique.'),
section('La synapse chimique','Dans le bouton présynaptique, des vésicules stockent un neurotransmetteur. Celui-ci est libéré dans la fente synaptique, puis rencontre des récepteurs de la membrane postsynaptique. Les deux membranes sont séparées par un espace extracellulaire très étroit. L’enchaînement à retenir est électrique → chimique → réponse de la cellule cible.',{precision:'Cette séparation décrit les synapses chimiques. Il existe aussi des synapses électriques, avec des jonctions communicantes permettant un passage direct de courant entre cellules. Elles ne suivent pas le mécanisme vésicules–neurotransmetteur développé ici.'}),
section('La clé et la serrure','Le neurotransmetteur doit rencontrer un récepteur compatible. Glutamate, GABA et acétylcholine n’activent pas indifféremment tous les récepteurs. Une même molécule peut toutefois agir sur plusieurs sous-types de récepteurs, avec des effets différents. Pour expliquer une réponse, il faut donc connaître à la fois le neurotransmetteur, le récepteur et les conditions ioniques de la cellule cible.'),
section('Des connexions très nombreuses','Le repère « 1 000 à 10 000 » rappelle la richesse des connexions, mais varie beaucoup selon le neurone. Plusieurs contacts peuvent unir deux mêmes cellules : nombre de synapses et nombre de partenaires ne sont pas identiques. Les estimations du total cérébral dépendent de la méthode, de l’âge et de la définition retenue.',{precision:'Le 10¹⁵ cité dans le texte est un ordre de grandeur pédagogique, pas un nombre exact établi pour tout cerveau humain. Il n’est pas nécessaire de le transformer en constante pour comprendre ce cours.'})
],{figure:'synapse',takeaway:'Une synapse chimique transforme le PA présynaptique en un message chimique, puis en une réponse postsynaptique.',sources:['synapticRelease','postsynaptic'],relatedChapters:['c3-neurone','c3-action']}),
chapter('c4-release','Du PA à l’exocytose','Calcium, synaptotagmine et SNARE','Comprendre chaque étape de la libération, plutôt que mémoriser une flèche sans mécanisme.',['terminals','calciumChannels','calcium','vesicles','snare'],[
section('1. Le PA dépolarise le bouton','L’arrivée du PA modifie rapidement le potentiel de la membrane présynaptique. Le pic vers +30 mV est le repère du cours ; le mécanisme dépend de la dépolarisation et ne nécessite pas que chaque bouton atteigne exactement cette valeur. Des canaux Ca²⁺ voltage-dépendants de la zone active peuvent alors s’ouvrir.'),
section('2. Le calcium entre localement','La concentration de Ca²⁺ est beaucoup plus élevée à l’extérieur qu’à l’intérieur du bouton. Dans les conditions de cette synapse, l’ouverture des canaux provoque une entrée de Ca²⁺. Le calcium augmente surtout près des sites de libération : sa proximité avec les vésicules préparées permet une réponse rapide. Ne confonds pas cette entrée présynaptique avec le calcium postsynaptique passant plus tard par NMDA.'),
section('3. Une machinerie est déjà préparée','Certaines vésicules sont arrimées et préparées à fusionner. Les protéines SNARE, notamment synaptobrévine, syntaxine et SNAP-25, participent au rapprochement et à la fusion des membranes. La synaptotagmine est un capteur de calcium : la fixation de Ca²⁺ contribue à déclencher la fusion rapide. Le calcium ne tire pas une vésicule comme un aimant ; il agit sur des protéines dans une machinerie organisée.'),
section('4. La vésicule fusionne et libère son contenu','La membrane vésiculaire fusionne avec la membrane du bouton : c’est l’exocytose. Le neurotransmetteur est libéré dans la fente, diffuse, puis se fixe sur des récepteurs compatibles. Une partie de la membrane et du contenu vésiculaires sera recyclée. La transmission est probabiliste : un PA ne garantit pas toujours la libération de toutes les vésicules disponibles.'),
section('Fréquence des PA et quantité libérée','Une augmentation de la fréquence présynaptique peut augmenter la libération sur une période donnée, notamment par l’accumulation de calcium résiduel. C’est le lien pédagogique entre fréquence des PA et signal chimique. La relation n’est toutefois pas automatiquement proportionnelle : disponibilité des vésicules, facilitation, dépression et probabilité de libération modifient la réponse.',{precision:'Le codage n’est pas uniquement une fréquence moyenne. Le timing des PA et les neurones recrutés comptent aussi. Dans des conditions comparables, augmenter le stimulus ne rend pas simplement chaque PA plus haut.'})
],{figure:'synapse',lab:'release',takeaway:'PA → dépolarisation → canaux Ca²⁺ → entrée de Ca²⁺ → synaptotagmine/SNARE → fusion → neurotransmetteur.',sources:['synapticRelease'],relatedChapters:['c3-propagation']}),
chapter('c4-postsynaptic','PPSE, PPSI et potentiel d’action','Des réponses graduées','Lire les variations postsynaptiques sans les confondre avec un PA.',['epsp','ipsp','ionChannels','membrane','initialSegment'],[
section('Ouvrir un passage, modifier un courant','Un récepteur ionotrope est lui-même un canal activé par un ligand. Sa fixation modifie le passage d’ions. Un récepteur métabotrope agit par des protéines G et des cascades intracellulaires, pouvant notamment modifier des canaux. Dans les deux cas, la réponse dépend des conductances modifiées, des gradients ioniques et du potentiel de membrane.'),
section('PPSE : potentiel postsynaptique excitateur','Un PPSE augmente la probabilité d’un PA. Dans l’exemple du cours, un courant net entrant de charges positives provoque une petite dépolarisation : −70 → −69 mV. Le potentiel se rapproche du seuil illustratif de −50 mV. Il reste un signal gradué : son amplitude dépend notamment de la force et du nombre d’entrées activées.'),
section('PPSI : potentiel postsynaptique inhibiteur','Un PPSI réduit la probabilité d’un PA. Le modèle d’exercice représente l’inhibition par une variation négative, par exemple −70 → −72 mV. Une conductance au Cl⁻ tend à amener Vm vers son potentiel de renversement ; une conductance K⁺ peut aussi participer à l’inhibition.',{precision:'Inhiber ne signifie pas toujours hyperpolariser. Une conductance inhibitrice peut limiter un PPSE par effet de shunt, avec peu de variation de Vm, et parfois malgré une dépolarisation. Le récepteur et le potentiel de renversement, comparé au seuil, déterminent l’effet.'}),
section('Pourquoi un PA et un PPS ne sont pas identiques','Le PA est régénéré par des canaux voltage-dépendants et se propage le long de l’axone. Les PPS sont gradués et leur propagation passive s’atténue dans les dendrites et le soma. Le cours utilise environ 100 mV et 1 ms pour un PA, contre 1 mV et 10–50 ms pour un PPS. Ce sont des repères de comparaison, pas des valeurs universelles.'),
section('Plus petit ne signifie pas inutile','Un seul PPSE central est souvent sous le seuil. Plusieurs réponses peuvent se superposer ; une inhibition peut réduire leur efficacité. C’est précisément l’intégration de ces petites variations qui décide si les conditions de déclenchement d’un nouveau PA sont atteintes. « Pas de PA » ne signifie donc pas « pas de réponse » : la membrane a pu varier sans décharge.')
],{figure:'postsynaptic',takeaway:'PPSE/PPSI = réponses graduées à intégrer ; PA = signal régénératif déclenché sous certaines conditions.',sources:['postsynaptic','summation'],table:{headers:['Propriété','PA','PPS'],rows:[['Amplitude','Tout ou rien dans des conditions comparables','Variable ; ±1 ou −2 mV dans les exercices'],['Durée indicative','Ordre de la milliseconde','Souvent plus longue, selon le récepteur'],['Propagation','Régénérée le long de l’axone','Propagation passive atténuée'],['Conséquence','Transmission vers les terminaisons','Modifie la probabilité d’un nouveau PA']]}}),
chapter('c4-summation','Les sommations spatiale et temporelle','Additionner dans l’espace et le temps','Comprendre pourquoi la proximité des signaux compte.',['epsp','ipsp','dendrites','soma','initialSegment'],[
section('Sommation temporelle : une entrée répétée','Une même synapse est activée plusieurs fois à intervalles rapprochés. Le premier PPS n’a pas complètement disparu quand le suivant arrive : leurs effets se superposent. Si les événements sont très espacés par rapport à la durée du PPS, ils s’additionnent peu. Dans l’exemple du professeur, cinq secondes séparent largement deux réponses de quelques dizaines de millisecondes.'),
section('Sommation spatiale : plusieurs emplacements','Des synapses situées à différents endroits de la cellule sont activées à peu près en même temps. Leurs effets se combinent dans les dendrites et le soma et influencent le segment initial. Les entrées peuvent être excitatrices ou inhibitrices. « Spatiale » décrit la diversité des sites, pas l’obligation qu’ils soient très éloignés.'),
section('Dans la réalité : les deux ensemble','Plusieurs synapses s’activent à des instants différents. Le neurone intègre donc des signaux dans l’espace et dans le temps. Une inhibition simultanée peut diminuer la dépolarisation, tandis qu’une inhibition arrivée après une décharge ne supprime pas le PA déjà produit. Le moment où les entrées se chevauchent compte autant que leur nombre.'),
section('Distance et poids d’une synapse','Un PPS propagé passivement s’atténue généralement avec la distance. Son effet au site d’intégration n’est pas forcément égal à sa taille locale. La géométrie dendritique, les propriétés de membrane, la localisation de l’inhibition et des conductances actives modifient aussi ce poids. Il est donc trop simple d’affirmer qu’une synapse éloignée est toujours négligeable.'),
section('La somme du cours est un modèle','Pour les calculs, on suppose que toutes les contributions arrivent ensemble et que leurs amplitudes sont déjà celles à additionner au site d’intégration. Cela permet une somme algébrique. Le neurone réel intègre des conductances et des variations dépendant du voltage : les réponses ne s’additionnent pas toujours de manière parfaitement linéaire.',{precision:'L’atelier de calcul applique volontairement le modèle du professeur. Il ne simule ni la propagation dendritique ni une courbe réelle de PA.'})
],{figure:'postsynaptic',takeaway:'Temporelle = répétition d’une entrée ; spatiale = plusieurs sites ; réel = combinaison spatio-temporelle.',sources:['summation'],table:{headers:['Situation','Type de sommation'],rows:[['Une synapse, activations rapprochées','Temporelle'],['Plusieurs synapses, effets qui se chevauchent','Spatiale'],['Plusieurs sites et plusieurs instants','Spatio-temporelle']]}}),
chapter('c4-exercises','Calculer si le seuil est atteint','Les exercices à maîtriser','Poser les signes, calculer la somme, puis comparer au seuil.',['epsp','ipsp','initialSegment','membrane'],[
section('1. Calculer ce qu’il manque','Avec un repos à −70 mV et un seuil à −50 mV, il manque une dépolarisation nette de 20 mV. On soustrait le repos au seuil : −50 − (−70) = +20 mV. Le signe est positif parce qu’il faut devenir moins négatif. Ce calcul est valable avec les valeurs choisies ; il ne faut pas apprendre « 20 PPSE » comme une constante biologique.'),
section('2. Donner le bon signe à chaque contribution','Dans les exercices, un PPSE de 1 mV apporte +1 mV ; un PPSI de 2 mV apporte −2 mV. Ne soustrais pas une deuxième fois un nombre déjà négatif. Le plus simple est d’écrire chaque contribution avec son signe, puis de vérifier si l’inhibition a bien abaissé la somme.'),
section('3. Trouver le nombre minimal de PPSE','Sans inhibition, 20 PPSE de +1 mV donnent −70 + 20 = −50 mV : le seuil du modèle est atteint. Avec trois PPSI de −2 mV, l’inhibition totale est −6 mV. Il faut alors 26 PPSE de +1 mV : −70 + 26 − 6 = −50 mV. Le calcul porte sur des contributions supposées superposées, pas sur 26 événements espacés de plusieurs secondes.'),
section('4. Changer l’amplitude sans changer la méthode','Si chaque PPSE vaut +2 mV avec la même inhibition de −6 mV, il en faut 13 : 13 × 2 = 26 mV. Si le quotient n’est pas entier, on arrondit le nombre d’événements vers le haut pour atteindre le seuil. Avec +1,5 mV par PPSE et −6 mV d’inhibition, 17 événements apportent 25,5 mV, trop peu ; 18 apportent 27 mV.'),
section('5. Interpréter sans inventer la suite','Une somme sous le seuil signifie qu’aucun PA n’est déclenché par ces entrées dans le modèle. À −50 mV ou au-dessus, on indique « seuil atteint ». Le potentiel calculé avant décharge n’est pas le pic d’un PA. Les conditions de réfractarité et la dynamique du neurone réel ne sont pas représentées ici.')
],{lab:'integration',takeaway:'Écrire Vm = repos + excitation − inhibition ; comparer au seuil et préciser les hypothèses.',sources:['summation'],formulas:[{text:'Vm calculé = −70 + nE × aE − nI × aI',caption:'aE et aI sont des amplitudes positives ; le signe − représente ici l’inhibition.'},{text:'nE minimal = plafond[(20 + nI × aI) / aE]',caption:'Valable dans le modèle simultané, linéaire, avec repos −70 mV et seuil −50 mV.'}],worked:[{title:'Sans inhibition',steps:['Repos : −70 mV ; seuil : −50 mV.','19 × 1 mV → Vm = −51 mV : seuil non atteint.','20 × 1 mV → Vm = −50 mV.'],result:'20 PPSE suffisent dans ce modèle.'},{title:'Trois PPSI de 2 mV',steps:['Inhibition : 3 × 2 = 6 mV.','Excitation nécessaire : 20 + 6 = 26 mV.','Vm = −70 + 26 − 6 = −50 mV.'],result:'Il faut 26 PPSE de 1 mV, ou 13 PPSE de 2 mV.'}]}),
chapter('c4-termination','Arrêter le signal et entretenir la synapse','Transporteurs, glie et énergie','Comprendre comment la synapse peut produire des messages successifs.',['astrocyte','glutamate','gaba','vesicles','synapse'],[
section('Libérer ne suffit pas','Après la fixation, le neurotransmetteur se détache et la réponse doit pouvoir évoluer. Diffusion, recapture et parfois dégradation enzymatique contribuent à faire diminuer sa concentration. Les récepteurs ont aussi leur propre cinétique et peuvent se désensibiliser : laisser du neurotransmetteur présent ne garantit pas un courant constant indéfiniment.'),
section('Les transporteurs','Des protéines récupèrent des neurotransmetteurs dans des terminaisons neuronales et des cellules gliales, selon le système. Leur action dépend des gradients ioniques, indirectement entretenus par des pompes consommant de l’ATP. La recapture ne correspond pas à une vésicule qui aspire directement les molécules depuis la fente.'),
section('Les astrocytes : plus qu’un aspirateur','Ils contribuent fortement à la récupération du glutamate et participent à l’environnement ionique et métabolique de la synapse. Une partie du glutamate récupéré est transformée en glutamine, qui peut revenir aux neurones et contribuer à un nouveau cycle. Le partage exact des rôles diffère selon le transmetteur et les transporteurs ; toutes les synapses ne sont pas entourées de façon identique.'),
section('Tous les transmetteurs ne disparaissent pas de la même façon','Pour l’acétylcholine, l’acétylcholinestérase joue un rôle majeur en hydrolysant le neurotransmetteur ; la choline peut être récupérée. Glutamate et GABA reposent notamment sur des transporteurs. Retenir uniquement « tous les neurotransmetteurs sont repris par les astrocytes » ferait perdre cette différence.'),
section('Pourquoi l’ATP est indispensable','Mitochondries, production d’ATP, entretien des gradients, recyclage des vésicules et fonctionnement cellulaire sont liés. Le cerveau dépend d’un apport sanguin adapté, notamment pour l’oxygène et les substrats énergétiques. Une réduction importante de cet apport peut perturber rapidement le fonctionnement cérébral.',{precision:'Les réserves énergétiques sont limitées, mais le cerveau n’est pas totalement dépourvu de réserves ou d’autres substrats utilisables. L’effet d’une hypotension dépend notamment de son intensité, de sa durée et de l’autorégulation cérébrale.'})
],{figure:'synapse',takeaway:'Diffusion, transporteurs et enzymes terminent le message ; neurones et glie entretiennent les conditions du suivant.',sources:['transmitterClearance'],relatedChapters:['c3-glie','c3-equilibre']}),
chapter('c4-glutamate','La synapse glutamatergique','Un neurotransmetteur, plusieurs récepteurs','Distinguer AMPA, NMDA, kainate et récepteurs métabotropes.',['glutamate','epsp','nmda','ionChannels'],[
section('Un acteur majeur de l’excitation','Le glutamate est le principal neurotransmetteur excitateur du cerveau adulte. De nombreuses projections corticales sont glutamatergiques. La libération suit le mécanisme PA → Ca²⁺ → fusion vésiculaire. Une connexion longue distance n’est toutefois pas, à elle seule, une preuve du neurotransmetteur employé.'),
section('AMPA : une réponse rapide','Les récepteurs AMPA sont des canaux activés par le glutamate. Dans les conditions habituelles près du repos, leurs courants cationiques ont un effet net dépolarisant. Na⁺ peut entrer et K⁺ sortir : l’explication « entrée de sodium » décrit le bilan excitateur sans résumer toute la sélectivité du canal.'),
section('NMDA : ligand et voltage','Le récepteur NMDA est aussi ionotrope, mais son canal est fortement bloqué par Mg²⁺ aux potentiels négatifs. Une dépolarisation soulage ce blocage. Il est perméable notamment à Ca²⁺, Na⁺ et K⁺. Son activation nécessite du glutamate et un coagoniste, souvent glycine ou D-sérine. Le chapitre suivant détaille pourquoi cette combinaison compte.'),
section('Kainate et récepteurs métabotropes','Les récepteurs au kainate appartiennent à la famille ionotrope. Les récepteurs métabotropes au glutamate, ou mGluR, agissent via des protéines G et peuvent moduler l’activité et la libération. Ce ne sont pas simplement des versions plus lentes d’un même canal AMPA.',{precision:'La transcription hésite sur certains noms. La nomenclature est précisée ici à partir des références : AMPA, NMDA et kainate sont les grandes familles ionotropes ; mGluR désigne les récepteurs métabotropes. Ce complément est distinct d’un mot attribué avec certitude au professeur.'})
],{figure:'nmda',takeaway:'Glutamate : AMPA/NMDA/kainate = ionotropes ; mGluR = métabotropes. Le récepteur explique le mécanisme.',sources:['glutamateReceptors'],table:{headers:['Récepteur','Repère utile'],rows:[['AMPA','Réponse cationique rapide, souvent dépolarisante'],['NMDA','Bloc Mg²⁺ dépendant du voltage ; perméable au Ca²⁺'],['Kainate','Autre famille ionotrope'],['mGluR','Protéines G et modulation']]}}),
chapter('c4-nmda','NMDA, calcium et plasticité','Lever le blocage au magnésium','Réunir les conditions d’activation sans confondre dépolarisation et neurotransmetteur.',['nmda','glutamate','calcium','hippocampus'],[
section('Au repos : un canal peut rester bloqué','À un potentiel suffisamment négatif, le Mg²⁺ extracellulaire bloque fortement le pore NMDA. Le glutamate peut se fixer sans produire un courant important par ce canal. « Récepteur activé par un ligand » et « courant ionique effectivement permis » ne sont donc pas exactement la même chose.'),
section('Dépolariser soulage le blocage','Une dépolarisation postsynaptique réduit le blocage voltage-dépendant par Mg²⁺. Un courant AMPA et d’autres entrées peuvent contribuer à cette dépolarisation. Il n’est pas nécessaire de rendre l’intérieur positif : la levée du blocage est graduelle, et une dépolarisation restant négative peut déjà l’atténuer.'),
section('Trois conditions à distinguer','Il faut du glutamate, un coagoniste compatible — glycine ou D-sérine dans les conditions habituelles — et un voltage permettant une levée suffisante du bloc Mg²⁺. Dépolariser seul ne fournit pas le ligand manquant ; ajouter seulement du glutamate au repos ne lève pas complètement le bloc. L’atelier représente ces conditions par trois choix, sans prétendre calculer une probabilité d’ouverture exacte.'),
section('Le calcium postsynaptique déclenche des cascades','Le Ca²⁺ passant par NMDA peut agir comme signal intracellulaire. Selon son profil et le contexte, il participe à des changements durables de l’efficacité synaptique, comme la potentialisation ou la dépression à long terme. Cette plasticité contribue à des mécanismes d’apprentissage et de mémoire, notamment étudiés dans l’hippocampe.'),
section('Ce qu’il ne faut pas conclure','Le calcium n’est pas une mémoire déposée dans le neurone, et chaque activation de NMDA ne crée pas automatiquement un souvenir. La mémoire implique des réseaux et plusieurs formes de plasticité. Le Ca²⁺ présynaptique déclenche la libération ; le Ca²⁺ postsynaptique via NMDA joue ici un rôle de signalisation : même ion, deux compartiments et deux étapes.')
],{figure:'nmda',lab:'nmda',takeaway:'Glutamate + coagoniste + levée du bloc Mg²⁺ → courant NMDA ; Ca²⁺ postsynaptique → cascades de plasticité.',sources:['glutamateReceptors','synapticPlasticity'],relatedChapters:['c2-memoire']}),
chapter('c4-gaba','GABA et inhibition','Le frein dépend du récepteur','Relier GABA_A, chlorure et potentiel de renversement.',['gaba','ipsp','ionChannels','membrane'],[
section('Un neurotransmetteur principalement inhibiteur','Dans de nombreux circuits du cerveau adulte, le GABA réduit la probabilité de décharge des cellules cibles. Des interneurones GABAergiques contribuent au contrôle local de l’activité, à son timing et à la coordination des réseaux. Dire « GABA = frein » est un mémo utile, pas une description complète de tous les contextes.'),
section('GABA_A et les anions','GABA_A est un récepteur ionotrope qui augmente une conductance anionique, principalement au Cl⁻, avec une contribution du bicarbonate. Dans le modèle du cours, Vm ≈ −70 mV et ECl ≈ −80 mV : l’ouverture favorise une entrée nette de Cl⁻ et tend à rendre Vm plus négatif. Le voltage se rapproche d’un potentiel de renversement ; le courant n’impose pas toujours exactement −80 mV.'),
section('Hyperpolarisation et shunt','Une conductance inhibitrice peut hyperpolariser, mais peut aussi réduire la taille d’une dépolarisation excitatrice sans modifier fortement le repos. C’est l’effet de shunt : augmenter la conductance limite l’effet d’autres courants. Une dépolarisation GABAergique peut donc encore être inhibitrice si elle ne mène pas au seuil et réduit l’efficacité des entrées excitatrices.',{precision:'Le signe dépend notamment des gradients de Cl⁻ et du potentiel de renversement. Ils changent avec le développement et dans certaines pathologies. On ne peut pas déduire « toujours excitateur » ou « toujours inhibiteur » de la seule entrée ou sortie d’un ion.'}),
section('GABA_B : une autre voie','GABA_B est métabotrope, couplé aux protéines G. Il peut notamment augmenter des conductances K⁺ postsynaptiques ou réduire des courants Ca²⁺ présynaptiques, modulant alors la libération. Assimiler tous les récepteurs du GABA à un canal Cl⁻ ferait disparaître cette différence.'),
section('Pourquoi le contrôle du chlorure compte','Des transporteurs entretiennent les concentrations de Cl⁻. Si leur fonctionnement change, le potentiel de renversement peut se déplacer et l’efficacité inhibitrice être modifiée. Le cours mentionne aussi des changements de disponibilité ou d’internalisation des récepteurs dans certaines situations pathologiques. Ce sont des mécanismes possibles, pas une explication unique de toutes les crises.')
],{figure:'gaba',lab:'ions',labIon:'Cl',takeaway:'GABA_A → conductance anionique ; GABA_B → protéines G. Inhibition ≠ hyperpolarisation obligatoire.',sources:['postsynaptic','gabaInhibition'],table:{headers:['Repère','À retenir'],rows:[['Glutamate','Principal transmetteur excitateur du cerveau adulte'],['GABA','Principal transmetteur inhibiteur de nombreux circuits adultes'],['Effet final','Dépend du récepteur, du voltage et des gradients']]}}),
chapter('c4-networks','Des synapses aux réseaux','Excitation, inhibition et états du cerveau','Comprendre les interactions entre l’accélérateur et le frein.',['glutamate','gaba','cortex','thalamus','eeg'],[
section('L’excitation peut recruter l’inhibition','Une cellule excitatrice peut activer d’autres cellules excitatrices mais aussi des interneurones inhibiteurs. Ceux-ci modulent la réponse de cellules voisines. L’inhibition feed-forward est recrutée par une entrée ; l’inhibition récurrente intervient dans une boucle de retour. Ces motifs contrôlent l’intensité et le timing de l’activité, sans former nécessairement une barrière anatomique autour d’un foyer.'),
section('Un équilibre dynamique','Le rapport excitation/inhibition n’est pas un nombre fixe ou une égalité permanente. Il varie selon les circuits, les moments et les tâches. L’inhibition ne sert pas seulement à empêcher les crises : elle contribue aussi à sélectionner des réponses, à synchroniser ou désynchroniser certaines activités et à traiter les informations.'),
section('Éveil et sommeil','Le cours associe l’état d’éveil à une disponibilité différente des fonctions cognitives. Le sommeil implique des changements de neuromodulation et d’organisation des réseaux, avec plusieurs stades. Il ne correspond pas à un cortex simplement éteint par plus de GABA : certaines activités persistent et le sommeil participe aussi à la consolidation de la mémoire.',{precision:'L’image « plus d’inhibition = sommeil = arrêt de l’apprentissage » est trop générale. Les états cérébraux combinent excitation, inhibition, neuromodulation et dynamique des réseaux.'}),
section('Que voit l’EEG ?','L’EEG recueille à la surface de la tête une activité électrique de populations, liée notamment à des courants postsynaptiques synchronisés. Ce n’est ni la somme directement lisible de tous les PA, ni une photo de chaque synapse. Son interprétation repose sur le contexte et les motifs observés.'),
section('Une activité peut devenir excessive','Des modifications de l’excitabilité, de l’inhibition, des connexions ou de la synchronisation peuvent favoriser une activité anormale. Le modèle accélérateur/frein aide à relier le chapitre aux crises, mais une crise ne s’explique pas toujours par une simple baisse uniforme des PPSI.')
],{takeaway:'Les réseaux règlent la force et le timing des réponses ; leur fonctionnement dépend de plusieurs mécanismes en interaction.',sources:['gabaInhibition','seizureClassification'],relatedChapters:['c2-eveil','c3-enregistrer']}),
chapter('c4-epilepsy','Comprendre les types de crises','Focale, généralisée et propagation','Relier les symptômes aux réseaux sans confondre propagation et origine.',['cortex','m1','v1','a1','thalamus','eeg'],[
section('Crise et épilepsie ne sont pas synonymes','Une crise épileptique est un événement transitoire lié à une activité neuronale anormale excessive ou synchrone. L’épilepsie décrit une prédisposition durable à produire certaines crises. Une crise isolée provoquée dans un contexte aigu ne suffit pas, à elle seule, à résumer ce diagnostic. Les exemples du cours servent à comprendre les réseaux, pas à identifier une maladie sur un seul comportement.'),
section('Les crises focales','Elles impliquent initialement des réseaux d’un hémisphère. Les manifestations dépendent des réseaux recrutés : phénomènes visuels, auditifs, sensations ou mouvements involontaires, parfois avec altération de la conscience. Une crise motrice d’origine corticale peut produire des signes du côté opposé. « Focale » n’impose pas qu’elle reste limitée à une seule petite tache pendant tout l’événement.'),
section('Les crises généralisées','Elles impliquent des réseaux bilatéraux d’emblée. Elles ne se résument pas à des convulsions de tout le corps : les absences sont un autre exemple. Les réseaux thalamo-corticaux peuvent être impliqués selon le type de crise. L’activité de chaque neurone du cerveau n’est pas nécessairement identique ou simultanée.'),
section('Quand une crise focale se propage','Une crise focale peut recruter d’autres régions puis produire une crise tonico-clonique bilatérale. On distingue cette évolution d’une crise généralisée d’emblée. Cette distinction précise le vocabulaire simplifié de la transcription.',{precision:'La classification ILAE mise à jour en 2025 distingue notamment les classes focale, généralisée, inconnue quant au caractère focal ou généralisé, et non classée. « Focale évoluant vers une crise tonico-clonique bilatérale » conserve l’information sur l’origine.'}),
section('Les crises gélastiques','Elles comportent un rire involontaire, souvent sans sentiment de joie. Elles peuvent notamment être associées à un hamartome hypothalamique, mais aussi à d’autres origines. Leur interprétation ne se limite donc pas à un « cortex du rire » ou à une émotion : ce sont des manifestations d’un réseau pathologique.')
],{takeaway:'Focale et généralisée décrivent des classes distinctes ; bilatéral après propagation ne prouve pas une origine généralisée.',sources:['seizureClassification','gelastic'],table:{headers:['Situation','Distinction à retenir'],rows:[['Réseau initial d’un hémisphère','Crise focale'],['Réseaux bilatéraux d’emblée','Crise généralisée'],['Focale puis convulsions bilatérales','Focale vers tonico-clonique bilatérale'],['Origine insuffisamment connue','Ne pas la déduire des seuls mouvements']]}}),
chapter('c4-context','Causes, déclencheurs et cibles pharmacologiques','Les exemples du cours expliqués','Distinguer ce qui favorise une maladie, déclenche une crise ou modifie un mécanisme.',['ionChannels','gaba','glutamate','snare','synapse'],[
section('Des origines diverses','Des variants génétiques peuvent modifier des canaux ou d’autres protéines. Des anomalies du développement, des lésions vasculaires, des traumatismes, des infections et des tumeurs peuvent être impliqués selon les situations. La classification étiologique comprend aussi des causes immunes, métaboliques et inconnues. Une épilepsie peut combiner plusieurs mécanismes.'),
section('Les convulsions de l’enfance demandent une précision','La transcription cite certaines convulsions importantes de l’enfance. Une association ou un facteur de risque n’est pas une causalité automatique. Les crises fébriles simples ne signifient pas que l’enfant développera une épilepsie ; des tableaux prolongés ou particuliers ont une autre signification clinique. Il faut garder la distinction entre événement, contexte et prédisposition.'),
section('Photosensibilité et exemple Pokémon','Certaines personnes sont sensibles à des stimuli visuels particuliers. Le cours cite une séquence de Pokémon ayant déclenché des événements chez des spectateurs. Le stimulus peut révéler ou déclencher une crise chez une personne sensible ; toutes les épilepsies ne sont pas photosensibles. Cet exemple est traité par du texte et des schémas fixes, sans reproduire les flashs.'),
section('Les traitements agissent sur plusieurs cibles','Le professeur oppose réduire l’excitation et renforcer l’inhibition. Des médicaments peuvent moduler des canaux Na⁺ ou Ca²⁺, certains récepteurs, la libération synaptique ou le métabolisme de neurotransmetteurs. Comprendre la cible aide à expliquer l’effet ; il n’existe pas une seule stratégie « plus de GABA » adaptée à tous les types de crises.'),
section('La toxine botulinique illustre une autre étape','Elle coupe certaines protéines SNARE et réduit la libération d’acétylcholine aux terminaisons cholinergiques concernées, notamment à la jonction neuromusculaire. Le PA peut arriver alors que la transmission chimique est empêchée : le muscle n’est plus activé normalement. Des utilisations médicales locales exploitent cet effet dans des indications précises. L’exemple éclaire l’exocytose ; ce n’est pas un traitement général de l’épilepsie ni un bloc direct des canaux NaV.'),
section('Ne pas mélanger les mécanismes','Dans le cours 3, lidocaïne et TTX illustrent la perturbation de courants nécessaires au PA. Ici, la toxine botulinique agit sur la libération vésiculaire. Un défaut postsynaptique pourrait agir encore après cette étape. Situer le problème sur la chaîne est plus informatif que conclure simplement « le neurone ne communique plus ».')
],{figure:'synapse',takeaway:'Cause ≠ déclencheur ; canal du PA ≠ exocytose ≠ récepteur postsynaptique : situer le mécanisme.',sources:['epilepsyOverview','photosensitivity','botulinum'],relatedChapters:['c3-blocage']}),
chapter('c4-bilan','Réviser tout le cours sans se mélanger','La chaîne et les calculs essentiels','Organiser les connaissances et vérifier ce que tu peux expliquer sans aide.',['synapse','epsp','ipsp','nmda','gaba','glutamate'],[
section('Raconter une transmission complète','Pars du PA présynaptique. Nomme la dépolarisation, les canaux Ca²⁺, l’entrée de calcium, la synaptotagmine et les SNARE, la fusion, le neurotransmetteur, le récepteur, puis la réponse postsynaptique. Place chaque événement dans le bon compartiment. Pour finir, explique que cette réponse s’intègre avec les autres avant un éventuel nouveau PA.'),
section('Maîtriser les termes et les comparaisons','Sache développer PPSE et PPSI, distinguer PA et PPS, reconnaître sommations temporelle, spatiale et spatio-temporelle, puis comparer glutamate et GABA. Pour NMDA, vérifie la présence des ligands et la levée du bloc Mg²⁺. L’inhibition peut agir sans hyperpolarisation importante : conserve cette précision derrière le mémo accélérateur/frein.'),
section('Refaire les calculs de base','Avec −70 mV de repos et −50 mV de seuil, cherche +20 mV nets. Sans inhibition : 20 PPSE de 1 mV. Avec trois PPSI de 2 mV : 26 PPSE de 1 mV. Change ensuite l’amplitude et arrondis le nombre minimal vers le haut. Chaque réponse doit citer les hypothèses de simultanéité et d’addition linéaire.'),
section('Expliquer les exemples, sans remplacer la règle par l’anecdote','ATP et astrocytes éclairent l’entretien de la synapse. Toxine botulinique éclaire la fusion vésiculaire. Les crises et la photosensibilité éclairent des propriétés de réseaux. Une anecdote ne suffit pas à définir tous les cas d’une maladie ou tous les mécanismes d’un récepteur.'),
section('Des priorités de révision, pas une prédiction d’examen','Le texte fourni comporte une partie hors cours sur ce qui pourrait tomber au contrôle. Ici, elle sert à organiser le travail : vocabulaire, chaîne de transmission, sommations et calculs d’abord, puis récepteurs, plasticité et réseaux. Sans consignes d’évaluation vérifiées, aucune question n’est annoncée comme certaine au contrôle.')
],{lab:'integration',takeaway:'Savoir placer les étapes, justifier les effets et refaire les calculs vaut mieux qu’une liste de mots isolés.',sources:['summation','postsynaptic'],formulas:[{text:'−70 + 26 × 1 − 3 × 2 = −50 mV',caption:'Le seuil du modèle est atteint ; le pic du PA n’est pas cette somme.'}],relatedChapters:['c3-action','c4-release','c4-exercises']})
]};
